const os = require("os");
const path = require("path");
const nock = require("nock");
const request = require("../../../../../../../../../../subject_repositories/image-downloader/lib/request.js");

describe("request", () => {
  afterEach(() => {
    nock.cleanAll();
  });

  it("rejects with the response status code when the HTTP status is not 200", async () => {
    nock("http://example.com")
      .get("/image.jpg")
      .reply(404, "Not Found");

    const dest = path.join(os.tmpdir(), "image-downloader-status-test.jpg");

    await expect(
      request({
        url: "http://example.com/image.jpg",
        dest
      })
    ).rejects.toThrow("Request Failed.\nStatus Code: 404");
  });
});
